function json(body,status=200){return new Response(JSON.stringify(body),{status,headers:{'content-type':'application/json; charset=utf-8','cache-control':'no-store'}});}
export async function onRequestGet({request,env}){if(!env.VENDOR_MEDIA)return json({ok:false,error:'image_storage_not_configured'},503);const key=new URL(request.url).searchParams.get('key')||'';if(!/^vendors\/\d+\/[a-f0-9-]+\.(jpg|png|webp|avif)$/i.test(key))return json({ok:false,error:'invalid_image_key'},400);try{const object=await env.VENDOR_MEDIA.get(key);if(!object)return new Response('Not found',{status:404});const headers=new Headers();object.writeHttpMetadata(headers);headers.set('etag',object.httpEtag);headers.set('cache-control','public, max-age=86400');headers.set('x-content-type-options','nosniff');return new Response(object.body,{headers});}catch(e){console.error('Vendor image read failed',e);return new Response('Image unavailable',{status:500});}}
export async function onRequest(){return json({ok:false,error:'method_not_allowed'},405);}
